export const LockedOptions: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const options = [
      { label: "Super Admin", value: "superadmin", disabled: true },
      { label: "Admin", value: "admin" },
      { label: "Editor", value: "editor" },
      { label: "Contributor", value: "contributor" },
      { label: "Guest", value: "guest" },
    ];
    const lockedOptions = [options[0]];
    const [value, setValue] = useState<ComboBoxDefaultOption[]>(lockedOptions);
    const handleChange = (newValue: ComboBoxDefaultOption[]) => {
      if (newValue.length === 0) {
        setValue(lockedOptions);
        return;
      }
      setValue(newValue);
    };
    return (
      <div className="w-480">
        <ComboBox
          hideClearOnDisabled
          multiple
          options={options}
          placeholder="Choose user role(s)"
          value={value}
          onChange={handleChange}
        />
      </div>
    );
  },
};

