export const CreatableDialog: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [value, setValue] = useState<ComboBoxDefaultOption>();
    const [options, setOptions] = useState([
      { label: "Elixir", value: "elixir" },
      { label: "JavaScript", value: "js" },
    ]);
    const [newOption, setNewOption] = useState<ComboBoxDefaultOption>();

    const closeDialog = () => setNewOption(undefined);
    const submitDialog = React.useCallback(() => {
      if (!newOption) return;
      // add the new edited option to the list of options
      setOptions([...options, newOption]);
      // clear the "newOption" state responsible for the dislay of the Dialog
      setNewOption(undefined);
      // set the value of the ComboBox to the newly created option
      setValue(newOption);
    }, [options, newOption]);

    return (
      <div className="w-288">
        <ComboBox
          creatable
          onChange={(val: any) => setValue(val)}
          onCreate={(value: string) => setNewOption({ label: value, value })}
          options={options}
          placeholder="Choose your language"
          value={value}
        />
        {newOption && (
          <Dialog open onClose={closeDialog}>
            <DialogHeader>Create new option</DialogHeader>
            <DialogContent>
              <FormControl label="Label" required>
                <Input
                  value={newOption.label}
                  onChange={(_, val) =>
                    setNewOption({ ...newOption, label: val })
                  }
                />
              </FormControl>
              <FormControl label="Value" required>
                <Input
                  value={newOption.value}
                  onChange={(_, val) =>
                    setNewOption({ ...newOption, value: val })
                  }
                />
              </FormControl>
              <pre>{JSON.stringify(newOption)}</pre>
              <DialogActions>
                <Button variant="secondary" onClick={closeDialog}>
                  Cancel
                </Button>
                <Button variant="primary" onClick={submitDialog}>
                  Create
                </Button>
              </DialogActions>
            </DialogContent>
          </Dialog>
        )}
      </div>
    );
  },
};

