export const CopyPaste: Story = {
  parameters: { docs: { source: { type: "code" } } },
  render: () => {
    const [value, setValue] = useState<string[]>([]);
    const options = ["Rust", "Elixir", "Kotlin", "JavaScript", "Elm", "Scala"];
    const handlePaste = (evt: React.ClipboardEvent) => {
      evt.preventDefault();
      // extend this implementation to manage unfound values or other edge cases
      const rawValue = evt.clipboardData.getData("text");
      let values: string[];
      if (rawValue.indexOf(",") >= 0) {
        values = rawValue.replace(/ /g, "").split(",");
      } else {
        values = rawValue.split(" ");
      }
      setValue(values);
    };
    return (
      <div className="w-288">
        <ComboBox
          placeholder="Choose a language"
          options={options}
          multiple
          value={value}
          onChange={setValue}
          onPaste={handlePaste}
        />
      </div>
    );
  },
};
